-- Grant the no-login runtime role its table operations; all business tables remain constrained by tenant RLS.
GRANT USAGE ON SCHEMA public TO lexa_app_runtime;
GRANT SELECT,INSERT,UPDATE,DELETE ON TABLE public.tenants, public.branches, public.users, public.memberships, public.branch_memberships, public.audit_events, public.module_records, public.module_record_links, public.module_domain_events, public.idempotency_records, public.platform_attachments, public.platform_jobs, public.platform_import_rows, public.platform_job_attempts, public.platform_job_replays, public.platform_restore_approvals, public.platform_provider_operations, public.platform_webhook_events, public.products, public.categories, public.product_variants, public.unit_of_measures, public.price_lists, public.price_list_items, public.tax_codes, public.tax_rules, public.tax_code_rule_versions, public.tax_reference_documents, public.tax_rule_reference_links, public.warehouses, public.storage_bins, public.stock_movements, public.stock_reservations, public.inventory_lots, public.inventory_serials, public.inventory_packages, public.inventory_package_lines, public.inventory_picklists, public.inventory_picklist_lines, public.inventory_replenishment_policies, public.inventory_stock_counts, public.inventory_stock_count_lines, public.inventory_transfers, public.inventory_transfer_lines, public.sales, public.sale_lines, public.sale_payments, public.sale_returns, public.sale_return_lines, public.commerce_sales_orders, public.commerce_sales_order_lines, public.commerce_fulfilments, public.commerce_fulfilment_lines, public.commerce_stock_reservations, public.commerce_deliveries, public.commerce_delivery_agents, public.commerce_delivery_items, public.commerce_delivery_events, public.commerce_delivery_collection_reports, public.commerce_delivery_collection_lines, public.commerce_delivery_remittances, public.commerce_delivery_remittance_allocations, public.commerce_purchase_orders, public.commerce_purchase_order_lines, public.commerce_goods_receipts, public.commerce_goods_receipt_lines, public.procurement_suppliers, public.procurement_purchase_requests, public.procurement_purchase_request_lines, public.procurement_rfqs, public.procurement_rfq_lines, public.procurement_rfq_suppliers, public.procurement_awards, public.procurement_approvals, public.procurement_approval_rules, public.procurement_supplier_notes, public.procurement_supplier_returns, public.procurement_supplier_return_lines, public.supplier_quotations, public.supplier_quotation_lines, public.ap_supplier_invoices, public.ap_supplier_invoice_lines, public.ap_supplier_payments, public.ap_supplier_payment_allocations, public.ar_customer_invoices, public.ar_customer_invoice_lines, public.ar_customer_receipts, public.ar_customer_receipt_allocations, public.credit_notes, public.credit_note_lines, public.ledger_accounts, public.ledger_journals, public.ledger_journal_lines, public.accounting_periods, public.cash_sessions, public.cash_movements, public.cash_ups, public.bank_accounts, public.bank_reconciliations, public.bank_reconciliation_matches, public.bank_statement_lines, public.expenses, public.expense_categories, public.fixed_assets, public.fixed_asset_depreciations, public.hr_employees, public.hr_employee_compensation, public.hr_attendance, public.hr_leave_requests, public.hr_shifts, public.hr_employee_shift_assignments, public.hr_timesheets, public.hr_payroll_runs, public.hr_payroll_lines, public.hr_payroll_deductions, public.projects, public.project_tasks, public.project_cost_entries, public.manufacturing_boms, public.manufacturing_bom_lines, public.manufacturing_work_orders, public.manufacturing_work_order_materials, public.manufacturing_job_cards, public.manufacturing_job_card_steps, public.quality_inspection_plans, public.quality_inspection_plan_checks, public.quality_inspections, public.quality_inspection_results, public.support_cases, public.cost_centres, public.cost_centre_allocations, public.platform_event_attempts, public.platform_event_receipts, public.platform_event_replays TO lexa_app_runtime;
GRANT SELECT ON public.platform_backup_inventory, public.platform_import_templates TO lexa_app_runtime;
GRANT SELECT,INSERT,UPDATE ON public.platform_worker_heartbeats TO lexa_app_runtime;
-- The worker may discover durable jobs/events/attachments across tenants, but each actual business-data operation
-- uses a dedicated connection with app.tenant_id set and is still governed by the normal tenant policies.
ALTER TABLE platform_jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform_jobs FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS platform_jobs_tenant_scope ON platform_jobs;
CREATE POLICY platform_jobs_tenant_scope ON platform_jobs USING (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),'')) WITH CHECK (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),''));
ALTER TABLE platform_attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform_attachments FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS platform_attachments_tenant_scope ON platform_attachments;
CREATE POLICY platform_attachments_tenant_scope ON platform_attachments USING (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),'')) WITH CHECK (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),''));
ALTER TABLE module_domain_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE module_domain_events FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS module_domain_events_tenant_scope ON module_domain_events;
CREATE POLICY module_domain_events_tenant_scope ON module_domain_events USING (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),'')) WITH CHECK (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),''));
ALTER TABLE platform_runtime_controls ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform_runtime_controls FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS platform_runtime_controls_tenant_scope ON platform_runtime_controls;
CREATE POLICY platform_runtime_controls_tenant_scope ON platform_runtime_controls USING (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),'')) WITH CHECK (tenant_id::text=NULLIF(current_setting('app.tenant_id',true),''));
ALTER TABLE platform_import_rows ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform_import_rows FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS platform_import_rows_tenant_scope ON platform_import_rows;
CREATE POLICY platform_import_rows_tenant_scope ON platform_import_rows USING (EXISTS(SELECT 1 FROM platform_jobs j WHERE j.id=job_id AND j.tenant_id::text=NULLIF(current_setting('app.tenant_id',true),''))) WITH CHECK (EXISTS(SELECT 1 FROM platform_jobs j WHERE j.id=job_id AND j.tenant_id::text=NULLIF(current_setting('app.tenant_id',true),'')));
